{"code":"export const isHtmlRenderedContentType = (contentType: string) => {
	const contentTypeLower = contentType.toLowerCase();

	return (
		// The content-type can also contain a charset, e.g. "text/html; charset=utf-8"
		contentTypeLower.startsWith('text/html') || contentTypeLower.startsWith('application/xhtml+xml')
	);","desc":"trace 第 3 步也是调用链终点，isHtmlRenderedContentType() 函数体位于 html-sandbox.ts 第 19–25 行，接收由 setResponseHeaders() 传入的 contentType 字符串。函数仅调用 toLowerCase() 生成 contentTypeLower，随即对 'text/html' 与 'application/xhtml+xml' 做 startsWith 前缀匹配。由于缺少 trim() 预处理，含首尾空白的 contentType 在大小写转换后仍无法通过前缀匹配，函数返回 false，上游 needsSandbox 判定失效，CSP 保护头被跳过。","file":"packages/core/src/html-sandbox.ts","line":"19-25"}

